const statusCode = msg.statusCode;
const errorMsg = msg.error ? msg.error.message : "Unknown error";
const source = msg.error ? (msg.error.source ? msg.error.source.name : "Unknown node") : "Unknown node";
const now = new Date().toISOString();

let errorType = "unknown";
let isCritical = false;

if (!statusCode || statusCode === 0) {
    errorType = "network";
    isCritical = true;
} else if (statusCode === 401 || statusCode === 403) {
    errorType = "auth";
    isCritical = true;
} else if (statusCode === 404) {
    errorType = "not_found";
} else if (statusCode === 429) {
    errorType = "rate_limit";
} else if (statusCode >= 500) {
    errorType = "server";
    isCritical = true;
} else if (statusCode >= 400) {
    errorType = "client";
}

const errorEntry = {
    timestamp: now,
    type: errorType,
    critical: isCritical,
    statusCode: statusCode || null,
    message: errorMsg,
    source: source,
    url: msg.url || null
};

let errorLog = global.get("error_log") || [];
if (errorLog.length >= 100) {
    errorLog = errorLog.slice(-99);
}
errorLog.push(errorEntry);
global.set("error_log", errorLog);

const connectionName = msg.metadata?.connection_name || null;
const failedIdentifier = msg.metadata?.source?.identifier || null;

// Count failures per active connection/client when metadata exists.
// Fallback to source node name for generic errors outside active connections.
const failureKey = (connectionName && failedIdentifier)
    ? `${connectionName}::${failedIdentifier}`
    : source;

let failureCounts = global.get("failure_counts") || {};
failureCounts[failureKey] = (failureCounts[failureKey] || 0) + 1;
global.set("failure_counts", failureCounts);

msg.errorEntry = errorEntry;
msg.failureCount = failureCounts[failureKey];
msg.failureKey = failureKey;
msg.connectionName = connectionName;
msg.failedIdentifier = failedIdentifier;
msg.isCritical = isCritical;

node.error(`[${errorType.toUpperCase()}] ${source}: ${errorMsg} (status: ${statusCode || "none"})`);

return msg;

/**
 * Emits the same payload shape used by Notify Connection Lifecycle:
 * {
 *   payload: connection,
 *   event: "lost",
 *   failed_identifier: "<client identifier>"
 * }
 *
 * Trigger at 5 failures, then 15, 25, 35...
 * Only for critical errors tied to a real active connection/client.
 */
const count = msg.failureCount;

const shouldNotify = count === 5 || (count > 5 && (count - 5) % 10 === 0);
if (!shouldNotify) {
    return null;
}

if (!msg.isCritical) {
    return null;
}

const connectionName = msg.connectionName;
const failedIdentifier = msg.failedIdentifier;

if (!connectionName || !failedIdentifier) {
    return null;
}

const connection = (global.get("parat_bridge.connections") || {})[connectionName];
if (!connection || !connection.clients) {
    return null;
}

// One-shot guard: do not emit multiple lost events for the same inactive connection.
if (!connection.active) {
    return null;
}

// Mark inactive so polling stops and later producers stay quiet.
global.set("parat_bridge.connections." + connectionName + ".active", false);

return {
    payload: connection,
    event: "lost",
    failed_identifier: failedIdentifier
};
